mapper.select:
SELECT id, user_id, type, actor_id, article_id, comment_id,
       content_preview, is_read, created_at
FROM notifications
WHERE user_id = #{userId}

    AND is_read = 0


    AND (created_at < #{cursorTime}
         OR (created_at = #{cursorTime} AND id < #{cursorId}))

ORDER BY created_at DESC, id DESC
LIMIT #{limit}

